-- ==========================================
-- RTG DRIVER PLANNER — Import du planning CER réel (septembre 2026)
-- ==========================================
-- À exécuter dans Supabase : Project > SQL Editor > New query.
--
-- Importe les repos / repos compensatoires / congés / maladies RÉELS
-- relevés sur le fichier PLANING_CER_SEPTEMBRE_2026_DES_3_SHIFTS.xlsx
-- (envoyé par l'exploitant le 28/09/2026), au lieu de laisser le moteur
-- automatique régénérer un planning théorique pour un mois déjà largement
-- écoulé — demande explicite de l'exploitant après avoir constaté que les
-- repos/congés affichés ne correspondaient pas au fichier réel.
--
-- Génération : les cellules "R"/"RC" du fichier deviennent une ligne
-- manual_overrides (prime toujours sur le calcul automatique — voir
-- planningEngine.js) ; les blocs contigus de cellules "C" (congé) et "M"
-- (maladie) deviennent des enregistrements conges/maladies (mêmes tables
-- que RTG/CC, AbsenceEngine les lit de la même façon) ; les cellules
-- "S1"/"S2" des conducteurs CDI (shift saisi manuellement chaque jour,
-- jamais calculé automatiquement — § migration_023) deviennent aussi une
-- ligne manual_overrides avec le shift et l'horaire correspondant.
-- Idempotent (ON CONFLICT / NOT EXISTS) : peut être rejouée sans dupliquer.

-- ---------- Repos / repos compensatoires / absences ponctuelles / shifts CDI ----------
-- (manual_overrides : une ligne par jour, prime toujours sur le calcul auto)
on conflict (date, driver_id) do update set shift = excluded.shift, status = excluded.status, start_time = excluded.start_time, end_time = excluded.end_time, motif = excluded.motif, updated_at = now();

on conflict (date, driver_id) do update set shift = excluded.shift, status = excluded.status, start_time = excluded.start_time, end_time = excluded.end_time, motif = excluded.motif, updated_at = now();

on conflict (date, driver_id) do update set shift = excluded.shift, status = excluded.status, start_time = excluded.start_time, end_time = excluded.end_time, motif = excluded.motif, updated_at = now();

on conflict (date, driver_id) do update set shift = excluded.shift, status = excluded.status, start_time = excluded.start_time, end_time = excluded.end_time, motif = excluded.motif, updated_at = now();

on conflict (date, driver_id) do update set shift = excluded.shift, status = excluded.status, start_time = excluded.start_time, end_time = excluded.end_time, motif = excluded.motif, updated_at = now();

-- ---------- Congés (blocs contigus 'C') ----------

-- ---------- Maladies (bloc 'M') ----------

-- Vérification.
select status, count(*) from manual_overrides where motif = 'Import planning réel CER (Excel, 28/09/2026)' group by status order by status;
select count(*) from conges where commentaire = 'Import planning réel CER (Excel, 28/09/2026)';
select count(*) from maladies where commentaire = 'Import planning réel CER (Excel, 28/09/2026)';